            size_t new_len = result_len + bytes_read;
            char *new_result = realloc(result, new_len + 1);
            if (new_result == NULL) {
                free(result);
                close(pipefd[0]);
                return strdup(""); // Return empty string on realloc error
            }
            result = new_result;
