            memcpy(result + result_len, buffer, bytes_read);
            result_len = new_len;
        }
        // Ensure the final result is null-terminated
        if (result != NULL) {
            result[result_len] = '\0';
        } else {
            // If no data was read, result is NULL. Allocate for an empty string.
            result = strdup("");
            if (result == NULL) {
                close(pipefd[0]);
                return NULL; // Indicate allocation failure
            }
        }
        close(pipefd[0]); // Close read end of pipe

